class ExamRoom { private final int n;private final TreeSet<Integer> occupied=new TreeSet<>();public ExamRoom(int n){this.n=n;}public int seat(){if(occupied.isEmpty()){occupied.add(0);return 0;}int candidate=0,best=occupied.first(),previous=occupied.first();for(int current:occupied.tailSet(previous,false)){int distance=(current-previous)/2;if(distance>best){best=distance;candidate=previous+distance;}previous=current;}if(n-1-previous>best)candidate=n-1;occupied.add(candidate);return candidate;}public void leave(int p){occupied.remove(p);} }
